#!/usr/bin/env python3
"""Build required report-name aliases and current master/next-step syntheses."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
REPORTS=ROOT/'reports'
def preserve_checkpoint_addenda(path, generated_text):
    existing=path.read_text(encoding='utf-8') if path.exists() else ''
    token='<!-- PRESERVE_CHECKPOINT_ADDENDA -->'
    if token in existing:
        tail=existing[existing.index(token):]
        return generated_text.rstrip()+'\n\n'+tail.lstrip()
    return generated_text

ALIASES={
 'PRECIPITATION_AUDIT.md':('RAIN_AUDIT.md','Kanonický povinný název pro konsolidovaný rain/rainRate audit.'),
 'DERIVED_VARIABLES_REPORT.md':('DERIVED_VARIABLE_AUDIT.md','Kanonický povinný název pro audit odvozených veličin.'),
 'DATA_QUALITY_CLASSIFICATION.md':('QUALITY_CLASSIFICATION_AUDIT.md','Kanonický povinný název pro návrh klasifikace a issue-level review registr.'),
 'LOCAL_SIMULATION_REPORT.md':('LOCAL_CORRECTION_SIMULATION.md','Kanonický povinný název pro lokální simulátor a jeho omezení.'),
}
for target,(source,note) in ALIASES.items():
 text=(REPORTS/source).read_text(encoding='utf-8')
 title=text.splitlines()[0]
 rest='\n'.join(text.splitlines()[1:])
 (REPORTS/target).write_text(f'{title}\n\n> {note} Zdrojový detail zachován v `{source}`.\n\n{rest.rstrip()}\n',encoding='utf-8')

consolidated='''# Konsolidovaný report korekčních návrhů a stavu\n\n**Stav:** žádný validovaný korekční balíček není připraven k aplikaci. Databáze je READ-ONLY; tento report není schválením zásahu.\n\n## Klasifikace současných návrhů\n\nPodrobné skupiny, počty a jejich provenience: `PROPOSAL_INVENTORY.md` a `2026-11-13-proposal-inventory.csv`. Historická evidence se dělí na již aplikované/supersedované zásahy, nereprodukovaný externí zásah 2021, pending návrhy se zastaralou časovou referencí a source-only případy bez archive row.\n\n- Phase A rain 2009–2011: 360 targetů mají applied history a current/latest-event účetní shodu; 19 bylo později supersedováno nulou→NULL. Neopakovat ani nevracet bez nového důkazu.\n- Fáze A obsahuje další tři aplikované target-variable zásahy; rainRate 2025 je konfliktní s pozdější historií.\n- July 2021 externí SQL: 8 921 archivních řádků, 8 920 přesných shod při WeeWX hranici, sedm chybějících plánovaných timestampů; původní SQL/hash chybí. Pouze diagnostika; žádné proposals.\n- Snapshot 2026-11-12: 20 pending batches / 272 kandidátů. 58 target-variable cílů má po založení pozdější applied historii (59 eventů); současný stav odpovídá latest eventu. Osm candidate cílů je Q1 2018 interim, nula je v 2021; dva cíle nemají archive row ani history event.\n- Z těchto počtů nelze odvodit validovaný počet korekcí: `validated_recommended_corrections=0`; podmíněné/stale počty se nepřevádějí na doporučení.\n\n## Aplikační hranice\n\nNeschválené pending hodnoty se nesmí považovat za nové hodnoty. Všechny budoucí proposals potřebují per-row source/time/unit lineage, target old-value, deduplikaci po `(timestamp, variable)`, dependency ordering a nové ověření current state. Q1 2018 zůstává interim; 2021 je chráněný. Změny do produkce, reconstruction, stagingu či derived tables nebyly provedeny.\n\n## Ověřitelnost\n\nHistorical inventory: `PROPOSAL_INVENTORY.md`; current-state reconciliation: `2026-11-12-pending-candidate-reconciliation.md`; applied rain accounting: `2026-11-13-rain-phaseA-history-reconciliation.md`; simulation methodology (synthetic only): `LOCAL_SIMULATION_REPORT.md`.\n'''
consolidated_path=REPORTS/'CONSOLIDATED_CORRECTIONS_REPORT.md'
consolidated_path.write_text(preserve_checkpoint_addenda(consolidated_path,consolidated),encoding='utf-8')
master='''# Souhrnný audit historických dat Počasí Loučka\n\n**Stav projektu:** rozsáhlý, reprodukovatelný, ale nedokončený audit. Produkční a rekonstrukční databáze zůstaly READ-ONLY. Nejsou publikovány ani aplikovány nové korekce. Tento report syntetizuje existující snapshoty s různými časy; nejde o jeden atomický stav.\n\n## Rozsah a výsledky po etapách\n\n- **A — databáze:** šest dostupných schémat, 102 tabulek a metadata 1 410 sloupcových definic; vybrané přesné archive a auxiliary counts jsou v `DATABASE_INVENTORY.md`. Main reconstruction monthly snapshot má 1 689 890 archive rows. Rozsahy snapshotů se liší; metadata `TABLE_ROWS` jsou aproximace.\n- **B — čas:** 212 měsíčních skupin; 24 523 kandidátních delt; 44 delt alespoň 24 h. Podmíněný pětiminutový výpočet pro 44 dlouhých mezer je 97 048 slotů pouze hypoteticky; nejdelší mezera 2011-08-15 až 2012-03-01 má 57 183 hypotetických vnitřních slotů. Expected cadence, provozní epochs a příčiny nejsou prokázány.\n- **C/H — teplota a modely:** chronologické complete-case holdouty jsou reprodukovatelné, avšak regionální reference není lokální truth. LuhaMet test 2019–2020 obsahuje 192 235 párů; přímý baseline MAE/RMSE 1,4865/2,8520 °C. Syntetické interpolation masks nejsou skutečné výpadky; 24h interpolace tlumí maxima v průměru o 6,22 °C (n=494) a worst block error je 19,57 °C. Mrazy, inverze, extrémy a skutečné gap truth zůstávají nejisté.\n- **D — vlhkost:** exact-time reference availability pro 2015–2017 zahrnuje 38 582 pozitivních LuhaMet RH hodnot u NULL cílů bez historie, ale reference je `reference_only`; RH transfer/phase modely neospravedlňují plošnou náhradu. Applied RH 2022-04 a derived cascade jsou účetně screenovány; historická formule stále chybí.\n- **E — srážky:** 1 586 426 řádků v 17 ročních skupinách mimo 2021; 11 780 exact-source NULL/rain kandidátních cílů prošlo screeningem. Counter/reset a rainRate driver sémantika i nezávislá lokální gauge truth nejsou vyřešeny. 1 497 případů roku 2021 zůstává diagnostických.\n- **F — sekundární senzory:** široký range/availability screening, source crosschecks a technické kanály jsou v `SECONDARY_SENSORS_AUDIT.md`; identity a epochs nejsou kompletní. 790 `extraTemp2>80` hodnot a 32 soil temperature extrémů vyžadují ER-20; archivní shoda není nezávislá fyzická validace.\n- **G — reference:** CHMI cache má 34 unikátních hash-ověřených souborů; ERA5/ERA5-Land katalogově ověřeny, ale nebyly staženy. Souřadnice Loučka čidla nejsou doloženy, prostorovou reprezentativnost nelze uzavřít.\n- **I — korekční historie:** `reconstruction_changes` obsahuje 94 930 applied a 17 842 reverted událostí. 86 256/86 256 posledních stavů pro outTemp, RH, rain a rainRate mimo 2021 se v dřívějším snapshotu účetně shodovalo; to neprokazuje meteorologickou správnost.\n- **J/K — derived a kvalita:** 21 derived fields je zmapováno napříč šesti archive schématy; producer/formule a automatický recalculation lineage chybí. Klasifikační model je issue-level se 31 skupinami `REVIEW_REQUIRED`, nikoli plošná row-level klasifikace.\n- **L/M — kandidáti a simulace:** inventář 272 pending candidates odděluje stale/approved/applied/protected; 58 má novější applied history (59 eventů). Validovaný correction package není připraven. Lokální simulátor prošel 12 syntetických scénářů; celá offline unit suite dříve prošla 65 testy. Serverový API dry-run/rollback nebyl ověřen.\n- **N/O — nástroje a připravenost:** lokální audit CLI spouští allowlistované validátory a porovnává SHA-256 běhy. Předběžná matice zahrnuje 198 buněk (2009–2026 × 11 kanálů), 138 `REVIEW_REQUIRED`, 60 `NOT_AVAILABLE` podle celoročního NULL snapshotu a žádné `READY`. Není to finální readiness všech veličin.\n\n## Korekční počty a rozhodnutí\n\nPočet nových, validovaných doporučených korekcí: **0**. To neznamená, že audit nenašel anomálie; konkrétní náhrada nemá ve většině případů dostatečný nezávislý zdroj, epochovou sémantiku nebo nejistotu. Podmíněné/stale kandidáty zůstávají oddělené v `CONSOLIDATED_CORRECTIONS_REPORT.md`. Historické applied zásahy nejsou návrhem na opakování. Bez Q1 2018 dokončení a bez samostatného schválení 2021 zůstávají tato období chráněná.\n\n## Kritické blokátory před sjednoceným archivem\n\n1. Uzavřít identitu zdrojů/senzorů, fyzické epochs, jednotky a historické WeeWX/driver konfigurace.\n2. Odborně vyřešit dlouhý zimní gap 2011–2012, mrazy, inverze, missingness bias a modelovou nejistotu.\n3. Doložit lokální či dostatečně nezávislou referenční truth a uncertainty kalibraci před rekonstrukcí.\n4. Určit rain/rainRate counter a interval semantiku; ověřit July-2021 externí SQL nebo jej ponechat nereprodukovaný.\n5. Dokončit per-row provenance/quality, derived dependency lineage a bezpečný rebuild plan.\n6. Rozšířit readiness na všechny veličiny a zahrnout validovaný per-year correction/gap inventory; stávající `FINAL_ARCHIVE_READINESS.md` je výslovně předběžný.\n7. Pro budoucí aplikaci ověřit runtime dry-run, multi-operation sequencing, atomic rollback a current-state optimism; zatím jen syntetický lokální simulátor.\n\n## Hlavní artefakty\n\nReprodukovatelné SQL, Python skripty, agregované CSV/JSON a SHA-256 běhy zůstávají pod workspace `sql/readonly/`, `scripts/`, `reports/`, `runs/`. Povinné reporty jsou vyjmenovány v `reports/required-report-inventory.json`. Závěrečný ZIP zatím není vytvořen, protože auditní obsah/readiness není finální.\n'''
master_path=REPORTS/'MASTER_AUDIT_REPORT.md'
master_path.write_text(preserve_checkpoint_addenda(master_path,master),encoding='utf-8')
nextsteps='''# Další kroky auditu\n\nPořadí zachovává READ-ONLY a chrání Q1 2018 i 2021. Každý krok ukládá bounded evidence, SQL/script, validator a checkpoint.\n\n1. Rozšířit readiness matrix z 11 na všechny relevantní meteorologické a odvozené kanály; doplnit roční/monthly NULL a source availability z raw aggregate snapshots, ne očekávané 5min sloty.\n2. Vytvořit year-variable monthly/annual NULL inventory pro všechna archive fields a validovat jej proti exact source counts.\n3. Dokončit secondary channel cross-source coverage podle dostupných schema fields; prioritně soil sensors, pressure/barometer/altimeter, wind unit epochs, lightning semantics a battery/RSSI. Chybějící fyzickou konfiguraci ponechat jako ER.\n4. Odborně řešit ER-01/02/07/20/28/29/30: dlouhé gapy, mráz/inverze, model uncertainty, extra/soil identity a 2026 daily-summary source/history conflicts.\n5. Dokončit odvozené veličiny: nalézt historické WeeWX config/package/producers, ověřit formuli/epochu, vytvořit dependency-aware stale/rebuild proposal; nic nepřepočítávat do DB.\n6. Připravit source-specific, per-row validated correction packages jen pro cíle s nezávislým měřením nebo ověřeným posunem/jednotkou. Zatím validovaných nových recommendations = 0; žádný balík neaplikovat.\n7. Dokončit audit framework: year/variable/read-only source query orchestration, archive comparison, approved package schema checks a readiness generation; současné CLI zatím spouští lokální validátory a porovnává běhy.\n8. Požádat o odborné rozhodnutí pouze ke zdokumentovaným ER otázkám; pokračovat nezávislými analýzami bez čekání na ně.\n9. Po potvrzení všech reportů, validátorů, source manifests a policy checks vytvořit nezávislý ZIP `loucka_complete_historical_data_audit_v1.zip` s SHA-256 obsahem. ZIP zatím odložen, aby nevydával předběžný stav za finální.\n\n## Ochranné stavy\n\n- Q1 2018: `INTERIM_LIVE`; po souběžné práci znovu ověřit rozsah/current state, bez duplikace.\n- 2021: diagnostický režim, bez correction proposals a bez změn.\n- Dlouhé výpadky, mráz/inverze, model uncertainty a konflikty zdrojů: `REVIEW_REQUIRED` s odkazy do `EXPERT_REVIEW_REQUIRED.md`.\n'''
nextsteps_path=REPORTS/'NEXT_STEPS.md'
nextsteps_path.write_text(preserve_checkpoint_addenda(nextsteps_path,nextsteps),encoding='utf-8')
# machine-readable inventory, built from the required list and aliases
required=['MASTER_AUDIT_REPORT.md','DATABASE_INVENTORY.md','TIME_CONTINUITY_AUDIT.md','TEMPERATURE_AUDIT.md','HUMIDITY_AUDIT.md','PRECIPITATION_AUDIT.md','SECONDARY_SENSORS_AUDIT.md','REFERENCE_DATA_INVENTORY.md','MODEL_VALIDATION_REPORT.md','RECONSTRUCTION_HISTORY_AUDIT.md','DERIVED_VARIABLES_REPORT.md','DATA_QUALITY_CLASSIFICATION.md','CONSOLIDATED_CORRECTIONS_REPORT.md','LOCAL_SIMULATION_REPORT.md','FINAL_ARCHIVE_READINESS.md','PROTECTED_YEAR_2021_DIAGNOSTICS.md','ACTIVE_2018_RECONSTRUCTION_STATUS.md','NEXT_STEPS.md']
records=[]
for name in required:
 p=REPORTS/name
 records.append({'report':name,'exists':p.is_file(),'bytes':p.stat().st_size if p.exists() else 0,'provisional':name=='FINAL_ARCHIVE_READINESS.md','source_alias':next((src for target,(src,_) in ALIASES.items() if target==name),None)})
(REPORTS/'required-report-inventory.json').write_text(json.dumps({'generated_by':'scripts/build_final_report_bundle.py','required_report_count':len(required),'reports':records},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Built aliases and syntheses; reports:',len(required))
